{"summary":"Implemented replay_analyzer.py to stream JSONL, count malformed lines, and aggregate per-session turns and invalid outputs.","files":[{"path":"scripts/replay_analyzer.py","content":"import json


def analyze(path: str) -> dict:
    malformed_lines = 0
    sessions = {}

    with open(path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                malformed_lines += 1
                continue

            session_id = entry.get('sessionId')
            entry_type = entry.get('type')

            if session_id not in sessions:
                sessions[session_id] = {'turns': 0, 'invalid_output': 0}

            if entry_type == 'agent.turn':
                sessions[session_id]['turns'] += 1
            elif entry_type == 'error' and entry.get('code') == 'invalid_output':
                sessions[session_id]['invalid_output'] += 1

    return {
        'malformed_lines': malformed_lines,
        'sessions': sessions
    }"}]}
